import { enqueueCatalogSync, getCatalog, type CatalogProduct } from '@/lib/catalog';

const priceFormatter = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD'
});

const dateFormatter = new Intl.DateTimeFormat('en-US', {
  dateStyle: 'medium',
  timeStyle: 'short'
});

const availabilityTone = (availability: CatalogProduct['availability']) => {
  switch (availability) {
    case 'In stock':
      return 'good';
    case 'Low stock':
      return 'warn';
    default:
      return 'alert';
  }
};

const statusTone = (status: CatalogProduct['status']) => {
  switch (status) {
    case 'Active':
      return 'good';
    case 'Seasonal':
      return 'accent';
    default:
      return 'muted';
  }
};

export default async function Page() {
  const catalog = await getCatalog();
  const totalSkus = catalog.products.length;
  const lowStock = catalog.products.filter(
    (product) => product.availability === 'Low stock'
  ).length;
  const backorder = catalog.products.filter(
    (product) => product.availability === 'Backorder'
  ).length;
  const activeSkus = catalog.products.filter(
    (product) => product.status === 'Active'
  ).length;
  const totalInventory = catalog.products.reduce(
    (sum, product) => sum + product.inventory,
    0
  );
  const lastSynced = dateFormatter.format(new Date(catalog.updatedAt));

  async function syncCatalogAction() {
    'use server';
    await enqueueCatalogSync();
  }

  return (
    <div className=\"page\">
      <div className=\"background\" aria-hidden=\"true\" />
      <header className=\"hero\">
        <div className=\"hero-text\">
          <span className=\"eyebrow\">Admin Catalog</span>
          <h1>Product catalog command center</h1>
          <p>
            Fast, read-heavy browsing with background syncs from ERP and PIM. The
            list stays responsive while updates roll out across every catalog
            view.
          </p>
        </div>
        <div className=\"hero-callout\">
          <div>
            <p className=\"label\">Catalog version</p>
            <p className=\"value\">v{catalog.version}</p>
          </div>
          <div>
            <p className=\"label\">Last synced</p>
            <p className=\"value\">{lastSynced}</p>
          </div>
        </div>
      </header>

      <section className=\"stats\">
        <div className=\"stat-card\">
          <p className=\"stat-label\">Total SKUs</p>
          <p className=\"stat-value\">{totalSkus}</p>
          <p className=\"stat-caption\">Cached with tag “products”.</p>
        </div>
        <div className=\"stat-card\">
          <p className=\"stat-label\">Active assortment</p>
          <p className=\"stat-value\">{activeSkus}</p>
          <p className=\"stat-caption\">Focused on daily merchandising.</p>
        </div>
        <div className=\"stat-card\">
          <p className=\"stat-label\">Low stock</p>
          <p className=\"stat-value\">{lowStock}</p>
          <p className=\"stat-caption\">Keep an eye on replenishment.</p>
        </div>
        <div className=\"stat-card\">
          <p className=\"stat-label\">Backorder</p>
          <p className=\"stat-value\">{backorder}</p>
          <p className=\"stat-caption\">Downstream fulfillment impacts.</p>
        </div>
        <div className=\"stat-card\">
          <p className=\"stat-label\">Inventory units</p>
          <p className=\"stat-value\">{totalInventory}</p>
          <p className=\"stat-caption\">Across stocked SKUs.</p>
        </div>
      </section>

      <main className=\"content\">
        <section className=\"catalog\">
          <div className=\"catalog-head\">
            <div>
              <h2>Catalog list</h2>
              <p className=\"catalog-sub\">
                Cached results serve instantly; sync when upstream pricing or
                availability shifts.
              </p>
            </div>
            <div className=\"catalog-meta\">
              <span className=\"meta-pill\">Cache tag: products</span>
              <span className=\"meta-pill\">Background refresh</span>
            </div>
          </div>

          <div className=\"table-wrap\">
            <table>
              <thead>
                <tr>
                  <th>SKU</th>
                  <th>Product</th>
                  <th>Category</th>
                  <th>Price</th>
                  <th>Inventory</th>
                  <th>Availability</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {catalog.products.map((product) => (
                  <tr key={product.id}>
                    <td className=\"mono\">{product.sku}</td>
                    <td>
                      <div className=\"product\">
                        <span className=\"product-name\">{product.name}</span>
                        <span className=\"product-meta\">{product.vendor}</span>
                      </div>
                    </td>
                    <td>{product.category}</td>
                    <td className=\"mono\">{priceFormatter.format(product.price)}</td>
                    <td className=\"mono\">{product.inventory}</td>
                    <td>
                      <span
                        className={"'`chip ${availabilityTone(product.availability)}`}
                      >
                        {product.availability}
                      </span>
                    </td>
                    <td>
                      <span className={`chip ${statusTone(product.status)}`}>
                        {product.status}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>

        <aside className="panel">
          <div className="panel-card">
            <h3>Sync latest catalog</h3>
            <p>
              Trigger a background refresh from ERP/PIM. You can keep working
              while the cache updates and invalidates when complete.
            </p>
            <form action={syncCatalogAction}>
              <button type="submit">Sync latest catalog</button>
            </form>
            <div className="panel-meta">
              <span>Cache tag: products</span>
              <span>Async job</span>
            </div>
          </div>

          <div className="panel-card muted">
            <h3>Operational notes</h3>
            <ul>
              <li>Reads stay fast with a shared catalog cache.</li>
              <li>Sync runs in the background for eventual consistency.</li>
              <li>Pricing, inventory, and availability align shortly after.</li>
            </ul>
          </div>
        </aside>
      </main>

      <style jsx>{`
